{
  "name": "opencode-session-keepalive",
  "version": "1.0.3",
  "description": "opencode plugin that keeps idle sessions' prompt caches warm with minimal pings, and stops when it stops paying",
  "type": "module",
  "main": "./session-keepalive.js",
  "exports": {
    ".": "./session-keepalive.js"
  },
  "files": [
    "session-keepalive.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "anthropic",
    "claude",
    "prompt-cache",
    "keepalive",
    "cost-optimization"
  ],
  "author": "Henrique Van Klaveren",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/klaveren/opencode-session-keepalive.git"
  },
  "bugs": {
    "url": "https://github.com/klaveren/opencode-session-keepalive/issues"
  },
  "homepage": "https://github.com/klaveren/opencode-session-keepalive#readme",
  "scripts": {
    "test": "node --test",
    "release": "npm version patch && git push --follow-tags"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}
